import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from mk2 import *

page(dict(
 slug='checkout',
 title=T('마트 계산대, 줄을 하나로 서면 왜 더 빠를까', 'Why Is One Shared Checkout Line Faster?'),
 title_tag=T('마트 계산대 줄 서기 · 시뮬라티오 랩', 'Checkout Lines · Simulatio Lab'),
 desc=T('계산대도 손님도 똑같은데, 줄을 하나로 서느냐 따로 서느냐에 따라 기다리는 시간이 달라집니다. 두 가게를 나란히 돌려 보세요.',
        'Same cashiers, same customers, but one shared line and separate lines give different waits. Run two stores side by side.'),
 lead=T('가장 짧은 줄을 골라 섰는데 옆줄이 먼저 줄어든 적이 있나요? 줄은 짧을수록 빨리 빠질 것 같지만, 그건 운이 나빴던 것만이 아닐 수 있습니다. 그런데 계산대와 손님이 모두 똑같은 두 가게에서 한쪽은 줄을 하나로 세우고 다른 쪽은 계산대마다 따로 세우면, 같은 손님이 두 곳에서 전혀 다른 시간을 기다리게 됩니다. 왼쪽 가게와 오른쪽 가게에 똑같은 손님을 보내 보세요.',
        'Ever picked the shortest line, only to watch the one beside you clear first? That may not be just bad luck. Take two stores with identical cashiers and identical customers, one with a single shared line and one with a separate line per cashier, and the same customer can end up waiting very different times in each. Send the exact same shoppers to the left store and the right store and watch.'),
 model=[T('<b>왼쪽 가게(A)</b>는 줄이 하나입니다. 맨 앞 손님은 가장 먼저 빈 계산대로 갑니다. <b>오른쪽 가게</b>는 계산대마다 줄이 따로 있고, 도착한 손님이 한 번 줄을 고르면 바꾸지 않습니다. 고르는 방식은 B(사람 수가 가장 적은 줄), C(아무 줄이나), D(물건이 가장 적은 줄) 중에서 고릅니다.',
          '<b>The left store (A)</b> has a single line: the person at the front goes to the first free cashier. <b>The right store</b> has a separate line per cashier, and arriving customers pick one line and never switch. The choice rule is B (fewest people), C (any line) or D (fewest items).'),
        T('손님은 무작위로 도착하고(평균 간격은 붐빔 정도로 정해짐), 계산 시간은 평균 3분에 물건 수에 비례합니다. 두 가게에는 <b>똑같은 손님 목록</b>(도착 시각, 물건 수)이 들어가므로, 차이는 오직 줄 서는 방식에서 나옵니다.',
          'Customers arrive at random (the average gap follows from how busy the store is) and checkout takes 3 minutes on average, in proportion to the number of items. Both stores get <b>exactly the same customer list</b> (arrival times, items), so any difference comes only from how the lines are organized.'),
        T('화면의 점 하나가 손님, 점 크기가 물건 수입니다. 계산대가 놀고 있는데 다른 줄에는 손님이 기다리는 순간은 계산대가 빨갛게 표시됩니다. 금빛 고리가 \'나\'이고, 점을 누르면 다른 손님이 \'나\'가 됩니다.',
          'Each dot is a customer and its size shows the number of items. A cashier turns red when it is idle while somebody waits in another line. The gold ring is \'you\'; click a dot to make a different customer \'you\'.'),
        T('결과 숫자는 손님 15만 명을 돌린 긴 시간 평균이고, 화면 속 가게는 문을 연 지 2시간 뒤부터 2시간 동안의 한 장면입니다.',
          'The numbers on the cards are long-run averages over 150,000 customers; the store on screen is a 2-hour slice of one run, starting 2 hours after opening.')],
 sliders=[('k', T('계산대 수', 'Number of cashiers'), 2, 8, 1, 4, T('많을수록 한 줄로 합치는 이득도, 줄 따로의 낭비도 커져요', 'More cashiers make both the gain from merging lines and the waste from separate lines larger')),
          ('rho', T('붐비는 정도', 'How busy'), 50, 95, 1, 90, T('계산대가 평균 몇 %의 시간 동안 일하는가. 95에 가까우면 줄이 급격히 길어져요', 'The average share of time a cashier is working. Near 95 the lines get dramatically longer')),
          ('cv', T('계산 시간의 들쭉날쭉함', 'Variability of checkout time'), 0.3, 2.0, 0.1, 1.0, T('0.3은 모두 비슷한 시간, 1.0은 보통, 2.0은 어떤 손님은 아주 오래 걸려요', '0.3 means everyone takes about the same time, 1.0 is typical, 2.0 means some customers take very long'))],
 selects=[('strat', T('오른쪽 가게의 줄 고르는 방식', 'Line choice in the right store'), [('short', T('B 사람이 가장 적은 줄', 'B Fewest people')), ('random', T('C 아무 줄이나', 'C Any line')), ('items', T('D 물건이 가장 적은 줄', 'D Fewest items'))], 'short', T('왼쪽 가게는 언제나 한 줄(A)입니다', 'The left store is always a single line (A)'))],
 reroll=T('같은 설정, 다른 손님들', 'Same settings, different customers'),
 sections=[
  dict(title=T('① 두 가게를 나란히 보기', '① Two Stores, Side by Side'),
       p=T('위쪽 계산대, 아래쪽 줄입니다. 파란 왼쪽은 줄 하나, 오른쪽은 계산대마다 줄 하나입니다. 같은 손님이 같은 시각에 도착합니다. 금빛 고리의 \'나\'는 두 가게 모두에 있고, 아래 문장에서 내 기다림을 비교합니다.',
           'Cashiers are on top and the lines below. The blue left store has one line, the right store has one line per cashier. The same customers arrive at the same moments. The gold-ringed \'you\' is in both stores, and the line at the bottom compares your waits.'),
       id='c-store', rounded=True, anim=True, thumb=True, step=False,
       speeds=[('10', T('느리게', 'Slow')), ('20', T('보통', 'Normal')), ('60', T('빠르게', 'Fast'))], speed_default='20'),
  dict(title=T('② 붐비는 정도에 따른 평균 대기', '② Average Wait vs. Busyness'),
       p=T('가로는 계산대가 바쁜 정도, 세로는 평균 대기시간입니다. 실선은 시뮬레이션, 점선은 계산식으로 구한 값(이론)입니다. 무작위로 줄을 서면(빨강) 붐빌수록 그래프 밖으로 치솟고, 짧은 줄(주황)이나 물건 적은 줄(초록)은 한 줄(파랑)에 훨씬 가깝습니다.',
           'The horizontal axis is how busy the cashiers are and the vertical axis the average wait. Solid lines are the simulation, dashed lines are values from a formula (theory). With random line choice (red) the wait shoots off the chart as it gets busier, while the shortest line (orange) and fewest items (green) stay much closer to the single line (blue).'),
       id='c-mean', note='mean'),
  dict(title=T('③ 90% 손님이 기다리는 시간', '③ The Wait 90% of Customers Stay Under'),
       p=T('손님 10명 중 9명이 이 시간 안에 계산을 시작합니다. 평균보다 \'운이 나쁜 손님\'이 얼마나 오래 기다리는지를 보여 줍니다.',
           'Nine out of ten customers start checking out within this time. It shows how long the unlucky customers wait, which the average hides.'),
       id='c-p90', note='p90'),
  dict(title=T('④ 기다림의 분포', '④ Distribution of Waits'),
       p=T('파란 막대는 한 줄, 선은 오른쪽 가게의 방식입니다. 바로 계산하는 손님은 얼마나 되는지, 오래 기다리는 손님은 얼마나 되는지 비교해 보세요.',
           'Blue bars are the single line, the outline is the right store\'s method. Compare how many start immediately and how many wait a long time.'),
       id='c-hist'),
 ],
 says=T('계산대 4개, 붐빔 90%, 계산 시간 보통(들쭉날쭉함 1.0)에서 손님 10만 명을 5번 돌린 평균은 이렇습니다. 한 줄은 평균 6.1분, 90% 손님이 16.0분 안에 계산을 시작했습니다. 사람이 가장 적은 줄을 고르는 방식(B)은 평균 6.9분(한 줄의 1.13배), 90%는 18.3분이었고 손님의 44%가 뒤에 온 사람에게 추월당했습니다. 같은 손님을 한 줄과 비교하면 34%는 1분 넘게 더 기다리고 26%는 1분 넘게 덜 기다렸습니다. 아무 줄이나 서는 방식(C)은 평균 29.9분(4.9배)이었고, 물건이 가장 적은 줄을 고르는 방식(D)은 평균 6.5분(1.06배)이었습니다. 계산대가 놀고 있는데 다른 줄에 손님이 있는 시간은 B 11%, C 35%, D 5%였고, 한 줄은 0%입니다. 한 줄이 더 빠른 정도는 설정에 따라 달랐습니다. 덜 붐빌 때 상대적으로 더 컸고(붐빔 60%: B가 1.61배), 계산대가 많을수록 컸으며(2대 1.05배, 8대 1.28배), 계산 시간이 들쭉날쭉할수록 컸습니다(1.5에서 1.18배). 붐빔 95%에서는 1.06배로 줄었는데, 그때는 어느 방식이든 모두 크게 기다리기 때문입니다.',
        'Averages over five runs of 100,000 customers with 4 cashiers, 90% busy and typical checkout times (variability 1.0): the single line averaged 6.1 minutes, and 90% of customers started checking out within 16.0 minutes. Joining the line with the fewest people (B) averaged 6.9 minutes (1.13 times the single line), 90% within 18.3 minutes, and 44% of customers were overtaken by someone who arrived later. Compared with the single line for the same customers, 34% waited more than a minute longer and 26% waited more than a minute less. Choosing any line (C) averaged 29.9 minutes (4.9 times), and joining the line with the fewest items (D) averaged 6.5 minutes (1.06 times). The share of time a cashier was idle while someone waited in another line was 11% for B, 35% for C and 5% for D, and 0% for the single line. How much faster the single line was depended on the settings. The relative gap was larger when it was less busy (60% busy: B was 1.61 times), with more cashiers (2 cashiers 1.05 times, 8 cashiers 1.28 times) and with more variable checkout times (1.18 times at 1.5). At 95% busy it shrank to 1.06 times, because everyone waits a lot with any method.'),
 **{'not': T('실제 마트를 재현한 것이 아닙니다. 이 모델에서 손님은 한 번 줄을 고르면 바꾸지 않습니다(옆줄로 옮기는 행동은 넣지 않았으므로, 현실의 줄 바꾸기는 줄 따로의 불리함을 일부 줄여 줄 것입니다). 현실의 계산대에는 물건 적은 손님 전용 계산대, 셀프 계산대, 계산대가 닫히거나 열리는 일, 가격표를 확인하러 가는 일, 줄이 짧아 보이는 착시와 습관이 있지만 모두 넣지 않았습니다. 도착은 하루 내내 같은 속도의 무작위이고 계산 시간 분포는 이 프로젝트가 가정한 것으로 한국 마트의 실제 자료가 아닙니다. 따라서 \'줄을 하나로 세우면 반드시 이득\'이라는 뜻이 아니라, 이런 단순한 조건에서 줄을 합치는 것이 어떤 효과를 내는지 보여 주는 것입니다. 한 줄이 손님에게 늘 더 낫다고는 할 수 없으며(공간, 줄이 길어 보여 포기하는 손님 등) 매장이 줄 구조를 고르는 데는 이 모델에 없는 요인이 많습니다.',
                'This is not a reproduction of a real store. In this model customers pick a line once and never switch (lane switching, or jockeying, is not modeled, so real-world line switching would soften some of the disadvantage of separate lines). Real stores also have express lanes, self-checkouts, cashiers opening and closing, price checks, and the habits and illusions that make a line look short, none of which are modeled. Arrivals are random at a constant rate all day and the checkout-time distribution is this project\'s assumption, not data from Korean supermarkets. So this does not say a single line is always better; it shows what merging lines does under these simple conditions. A single line is not always better for customers (space, customers who balk at a long line), and a store weighs many factors this model leaves out.')},
 theory=[('root', T('대기행렬 이론입니다. 덴마크의 A. K. Erlang이 전화 교환기에서 통화를 기다리는 문제를 풀며 만든 계산식(얼랑 C)이 계산대 여러 개에 한 줄로 서는 가게(M/M/c)의 기본 이론이고, 줄 따로는 계산대마다 따로 계산하는 줄(M/M/1)이 여러 개 있는 경우와 같습니다.',
                    'This is queueing theory. The Erlang C formula, worked out by the Danish engineer A. K. Erlang for calls waiting in telephone exchanges, is the basic result for a single shared line feeding several cashiers (M/M/c), and separate lines behave like several independent single-cashier queues (M/M/1).')),
         ('model', T('붐빔 ρ = 도착률 × 평균 계산 시간 ÷ 계산대 수 (슬라이더 \'붐비는 정도\'). 계산대 c개, a = ρc일 때 손님이 도착해 기다려야 할 확률 C(c, a)를 얼랑 C 식으로 구하고, 평균 대기는 <code>Wq = C(c, a) × S / (c(1−ρ))</code> (S는 평균 계산 시간 3분), 기다림이 t를 넘을 확률은 <code>C × e<sup>−c(1−ρ)t/S</sup></code>입니다. 줄 따로이고 아무 줄이나 서면 계산대마다 M/M/1이 되어 <code>Wq = ρS / (1−ρ)</code>입니다.',
                     'Utilization ρ = arrival rate × mean checkout time ÷ number of cashiers (the \'How busy\' slider). With c cashiers and a = ρc, the Erlang C formula gives C(c, a), the probability that an arriving customer has to wait; the mean wait is <code>Wq = C(c, a) × S / (c(1−ρ))</code> with S the mean checkout time (3 minutes), and the chance of waiting longer than t is <code>C × e<sup>−c(1−ρ)t/S</sup></code>. With separate lines and random choice each cashier is an M/M/1 queue, <code>Wq = ρS / (1−ρ)</code>.')),
         ('simplify', T('계산 시간을 평균 3분의 감마분포(슬라이더로 들쭉날쭉함 조절)로, 물건 수는 평균 10개로 두고 계산 시간에 비례하게 정한 것은 이 프로젝트의 설정입니다. 들쭉날쭉함이 1.0이 아닐 때의 한 줄 이론선은 평균 대기에 (1+cv²)/2를 곱하는 흔한 근사이고, 무작위 줄은 폴라체크-힌친 평균 대기 공식입니다. 줄 바꾸기, 포기하는 손님, 전용 계산대는 넣지 않았습니다.',
                       'Checkout time is a gamma distribution with a mean of 3 minutes (the variability slider), and items average 10 and are proportional to checkout time; these are this project\'s choices. When variability is not 1.0, the single-line theory line uses the common approximation of multiplying the mean wait by (1+cv²)/2, and the random-line one is the Pollaczek-Khinchine mean wait formula. Line switching, balking and express lanes are not modeled.')),
         ('check', T('<code>node tools/validate-checkout.js</code>의 결과(시드 5개 × 손님 10만 명 평균, 들쭉날쭉함 1.0)입니다. 계산대 4개 붐빔 60%에서 한 줄 평균 대기는 시뮬레이션 0.54분, 이론 0.54분이고, 붐빔 80%는 2.25분 대 2.24분, 90%는 6.11분 대 5.91분이었습니다. 90% 손님 기준은 붐빔 90%에서 16.0분 대 15.5분입니다. 계산대 2개 붐빔 70%는 2.88분 대 2.88분이었습니다. 무작위 줄은 붐빔 60%에서 4.55분 대 4.50분, 80%에서 12.46분 대 12.00분, 90%에서 29.9분 대 27.0분으로 붐빌수록 시뮬레이션이 이론보다 높게 나왔습니다(유한한 손님 수 때문으로 보임). 들쭉날쭉함 1.5, 붐빔 90%에서 한 줄 근사는 9.60분으로 시뮬레이션 9.03분보다 약 7% 높았습니다.',
                        'From <code>node tools/validate-checkout.js</code> (average of 5 seeds × 100,000 customers, variability 1.0). With 4 cashiers at 60% busy the single line mean wait was 0.54 minutes in simulation and 0.54 in theory; at 80% it was 2.25 vs 2.24 and at 90% 6.11 vs 5.91. The 90th percentile at 90% busy was 16.0 vs 15.5 minutes. With 2 cashiers at 70% it was 2.88 vs 2.88. For random lines the simulation gave 4.55 vs 4.50 at 60% busy, 12.46 vs 12.00 at 80% and 29.9 vs 27.0 at 90%, so the simulation ran higher than theory as it got busier (likely due to the finite number of customers). With variability 1.5 and 90% busy the single-line approximation gave 9.60 minutes, about 7% above the simulated 9.03.')),
         ('read', T('Leonard Kleinrock, 『Queueing Systems, Volume 1: Theory』(Wiley, 1975). Donald Gross와 Carl M. Harris, 『Fundamentals of Queueing Theory』(Wiley). 줄을 합치는 것이 항상 이로운 것은 아니라는 점은 Rothkopf &amp; Rech (1987), "Perspectives on queues: combining queues is not always beneficial", <i>Operations Research</i>에서 다룹니다.',
                    'Leonard Kleinrock, <i>Queueing Systems, Volume 1: Theory</i> (Wiley, 1975). Donald Gross and Carl M. Harris, <i>Fundamentals of Queueing Theory</i> (Wiley). That combining queues is not always beneficial is discussed in Rothkopf &amp; Rech (1987), "Perspectives on queues: combining queues is not always beneficial", <i>Operations Research</i>.'))],
 memo=[T('시뮬레이션은 손님 목록(도착 시각, 계산 시간, 물건 수, 무작위 줄 선택용 난수)을 한 번 만들어 모든 방식에 똑같이 넣는 공통 난수 방식입니다. 시드 난수(mulberry32)를 쓰므로 같은 시드면 같은 결과가 나옵니다. 화면의 가게는 두 방식의 시작·끝 시각을 미리 계산해 두고 시간에 따라 위치만 그립니다.',
         'The simulation builds one customer list (arrival times, checkout times, items, and random numbers for the random choice) and feeds it identically to every method, a common random numbers design. It uses a seeded generator (mulberry32), so the same seed gives the same result. The store on screen precomputes each method\'s start and end times and just draws positions as time advances.'),
       T('추월당한 손님은 자기보다 늦게 도착한 사람이 더 먼저 계산을 시작한 손님입니다. 계산대가 놀면서 기다리는 사람이 있는 시간 비율은 시작과 끝 시각을 시간순으로 훑어 구했고, 처음 10% 손님은 가게가 비어 있던 시기라 통계에서 뺐습니다.',
         'An overtaken customer is one for whom someone who arrived later started checkout earlier. The share of time with an idle cashier while someone waits was found by sweeping start and end times in order, and the first 10% of customers, from when the store was still empty, were left out of the statistics.'),
       T('카드 숫자는 손님 15만 명을 한 번 돌린 값이라 페이지 설명(10만 명 × 5번 평균)과 조금 다를 수 있습니다. 검증은 <code>node tools/validate-checkout.js</code>로 할 수 있습니다.',
         'The numbers on the cards come from a single run of 150,000 customers, so they can differ slightly from the page text (an average of 5 runs of 100,000). You can verify with <code>node tools/validate-checkout.js</code>.')],
))
